-- PREPARED ONLY: unrestricted company actors only; scoped-record support remains blocked.
-- PREPARED ONLY: Q-01..Q-10 connected personnel evidence ledger. Do not execute without PostgreSQL/RLS/SDK review.
create schema if not exists care_personnel_private;
revoke all on schema care_personnel_private from public,anon,authenticated;
create table if not exists care_personnel_private.roots(tenant_id uuid not null,employee_id uuid not null,head_id uuid,updated_at timestamptz not null default clock_timestamp(),primary key(tenant_id,employee_id));
create table if not exists care_personnel_private.events(id uuid primary key,tenant_id uuid not null,employee_id uuid not null,sequence bigint not null,previous_id uuid,request_id uuid not null,actor_id uuid not null,actor_name text not null,occurred_at timestamptz not null,recorded_at timestamptz not null default clock_timestamp(),kind text not null,command jsonb not null,unique(tenant_id,employee_id,sequence),unique(tenant_id,request_id));
alter table care_personnel_private.roots enable row level security;alter table care_personnel_private.events enable row level security;
revoke all on all tables in schema care_personnel_private from public,anon,authenticated;revoke all on all functions in schema care_personnel_private from public,anon,authenticated;
create or replace function care_personnel_private.immutable()returns trigger language plpgsql security definer set search_path='' as $$begin raise exception using errcode='P0P01',message='personnel evidence is append only';end$$;
drop trigger if exists personnel_roots_delete on care_personnel_private.roots;create trigger personnel_roots_delete before delete on care_personnel_private.roots for each row execute function care_personnel_private.immutable();
drop trigger if exists personnel_events_immutable on care_personnel_private.events;create trigger personnel_events_immutable before update or delete on care_personnel_private.events for each row execute function care_personnel_private.immutable();
create or replace function care_personnel_private.actor(p_tenant uuid,p_actor uuid,p_write boolean default false)returns text language plpgsql security definer set search_path='' as $$declare n text;begin
 if auth.uid() is null or auth.uid()<>p_actor then raise exception using errcode='42501',message='session mismatch';end if;
 select concat_ws(' ',p.first_name,p.last_name) into n from public.profiles p join public.user_roles ur on ur.user_id=p.id and ur.tenant_id=p_tenant join public.roles r on r.id=ur.role_id where p.id=p_actor and p.tenant_id=p_tenant and p.is_active is true and p.status='active'and(p.auth_user_id is null or p.auth_user_id=auth.uid()) and r.key in('business_admin','business_manager','billing','dispatch') for share of p,r;
 if n is null or care_security.company_actor(p_tenant,'office.employees.view')is not true or care_security.company_actor(p_tenant,'office.employees.view_sensitive')is not true or(p_write and care_security.company_actor(p_tenant,'office.employees.edit')is not true)or public.has_permission('office.employees.view')is not true or public.has_permission('office.employees.view_sensitive')is not true or(p_write and public.has_permission('office.employees.edit')is not true) then raise exception using errcode='42501',message='current personnel permission missing';end if;return n;end$$;
create or replace function care_personnel_private.employee_original(p_tenant uuid,p_employee uuid)returns jsonb language sql security definer set search_path='' as $$select to_jsonb(e) from public.employees e where e.id=p_employee and e.tenant_id=p_tenant$$;
create or replace function care_personnel_private.sources(p_tenant uuid,p_employee uuid)returns jsonb language sql security definer set search_path='' as $$
 with s as(
  select 'employee'::text kind,e.id,to_jsonb(e) snapshot from public.employees e where e.tenant_id=p_tenant and e.id=p_employee
  union all select 'document',d.id,to_jsonb(d) from public.employee_documents d where d.tenant_id=p_tenant and d.employee_id=p_employee
  union all select 'qualification',q.id,to_jsonb(q) from public.employee_qualifications q where q.tenant_id=p_tenant and q.employee_id=p_employee
  union all select 'training',t.id,to_jsonb(t) from public.employee_training_records t where t.tenant_id=p_tenant and t.employee_id=p_employee
  union all select 'assignment',g.id,to_jsonb(g) from public.employee_assignment_eligibility g where g.tenant_id=p_tenant and g.employee_id=p_employee
  union all select 'absence',a.id,to_jsonb(a) from public.employee_absences a where a.tenant_id=p_tenant and a.employee_id=p_employee
  union all select 'time_entry',x.id,to_jsonb(x) from public.employee_time_entries x where x.tenant_id=p_tenant and x.employee_id=p_employee
  union all select 'access',z.id,to_jsonb(z) from public.employee_access_revocations z where z.tenant_id=p_tenant and z.employee_id=p_employee
  union all select 'access',pa.id,to_jsonb(pa) from public.employee_portal_access pa where pa.tenant_id=p_tenant and pa.employee_id=p_employee
  union all select 'safety',h.id,to_jsonb(h) from public.employee_hr_documents h where h.tenant_id=p_tenant and h.employee_id=p_employee
 )select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'id',id,'snapshot',snapshot)order by kind,id),'[]'::jsonb)from s$$;
create or replace function care_personnel_private.people(p_tenant uuid)returns jsonb language sql security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'profileId',e.profile_id,'tenantId',e.tenant_id,'name',concat_ws(' ',e.first_name,e.last_name),'roleKey',coalesce(e.role_title,'employee'),'active',true,'updatedAt',e.updated_at)order by e.last_name,e.first_name,e.id),'[]'::jsonb)from public.employees e where e.tenant_id=p_tenant and e.status in('active','aktiv')$$;
create or replace function care_personnel_private.history(p_tenant uuid,p_employee uuid)returns jsonb language sql security definer set search_path='' as $$select jsonb_build_object('version','2026-10-16.1','tenantId',p_tenant,'employeeId',p_employee,'count',count(e.id),'headId',r.head_id,'events',coalesce(jsonb_agg(jsonb_build_object('id',e.id,'sequence',e.sequence,'previousId',e.previous_id,'tenantId',e.tenant_id,'employeeId',e.employee_id,'actorId',e.actor_id,'actorName',e.actor_name,'recordedAt',to_char(e.recorded_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'command',e.command)order by e.sequence)filter(where e.id is not null),'[]'::jsonb))from care_personnel_private.roots r left join care_personnel_private.events e on e.tenant_id=r.tenant_id and e.employee_id=r.employee_id where r.tenant_id=p_tenant and r.employee_id=p_employee group by r.head_id$$;
create or replace function care_personnel_private.assert_source(p_tenant uuid,p_employee uuid,p_source jsonb)returns void language plpgsql security definer set search_path='' as $$declare actual jsonb;begin
 if jsonb_typeof(p_source)is distinct from'object'or(select count(*)from jsonb_object_keys(p_source))<>3 or not(p_source?'kind'and p_source?'id'and p_source?'snapshot')then raise exception using errcode='22023',message='source missing';end if;
 select x into actual from jsonb_array_elements(care_personnel_private.sources(p_tenant,p_employee))x where x->>'kind'=p_source->>'kind'and x->>'id'=p_source->>'id';if actual is distinct from p_source then raise exception using errcode='40001',message='source changed';end if;
end$$;

create or replace function care_personnel_private.valid_id(v jsonb)returns boolean language sql immutable set search_path='' as $$select coalesce(jsonb_typeof(v)='string' and(v#>>'{}')~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',false)$$;
create or replace function care_personnel_private.valid_text(v jsonb,max_units integer default 4000)returns boolean language sql immutable set search_path='' as $$select coalesce(jsonb_typeof(v)='string'and nullif(btrim(v#>>'{}'),'')is not null and(max_units=0 or(select coalesce(sum(case when ascii(c)>65535 then 2 else 1 end),0)from regexp_split_to_table(v#>>'{}','')c)<=max_units),false)$$;
create or replace function care_personnel_private.valid_date(v jsonb)returns boolean language plpgsql immutable set search_path='' as $$declare d date;begin if jsonb_typeof(v)is distinct from'string'or(v#>>'{}')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'then return false;end if;d:=(v#>>'{}')::date;return to_char(d,'YYYY-MM-DD')=v#>>'{}';exception when others then return false;end$$;
create or replace function care_personnel_private.valid_instant(v jsonb)returns boolean language plpgsql immutable set search_path='' as $$begin if jsonb_typeof(v)is distinct from'string'or(v#>>'{}')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'then return false;end if;perform(v#>>'{}')::timestamptz;return true;exception when others then return false;end$$;
create or replace function care_personnel_private.payload_contract(k text)returns jsonb language sql immutable set search_path='' as $$select '{"employment":{"employee":"source:employee","employmentType":"text","location":"text","role":"text","validFrom":"date","validUntil":"date?","decision":"text"},"qualification":{"qualification":"source:qualification","document":"source:document","activity":"text","validFrom":"date","validUntil":"date","result":"enum:verified,rejected,expired","reviewer":"person"},"delegation":{"assignment":"source:assignment","activity":"text","validFrom":"instant","validUntil":"instant","assignee":"person","qualificationEventId":"id","decision":"text"},"instruction":{"training":"source:training","document":"source:document","subject":"text","version":"text","instructor":"person","result":"enum:attended,instructed,not_passed","validUntil":"date"},"double_staffing":{"assignment":"source:assignment","primary":"person","secondary":"person","phase":"enum:planned,primary_ack,secondary_ack,cancelled","reason":"text","validFrom":"instant","validUntil":"instant"},"education_due":{"training":"source:training","document":"source:document","requirement":"text","dueAt":"instant","status":"enum:assigned,reminded,completed,verified,rejected"},"coverage":{"absence":"source:absence","delegate":"person","scope":"text","validFrom":"instant","validUntil":"instant","accessUntil":"instant","decision":"text"},"safety":{"safety":"source:safety","document":"source:document","hazard":"text","measure":"text","status":"enum:open,mitigated,accepted,rejected","responsible":"person"},"payroll_time":{"timeEntry":"source:time_entry","classification":"enum:work,travel,standby,break,not_payroll","startedAt":"instant","endedAt":"instant","decision":"text","reviewer":"person"},"absence":{"absence":"source:absence","category":"enum:sick,vacation,training,unavailable,other","validFrom":"instant","validUntil":"instant","decision":"text"},"return_decision":{"absence":"source:absence","decision":"enum:fit,restricted,not_fit","validFrom":"instant","validUntil":"instant","restrictions":"text","reviewer":"person"},"offboard":{"employee":"source:employee","exitDate":"date","reason":"text","accesses":"accesses","decision":"text"},"correct":{"targetId":"id","reason":"text"}}'::jsonb->k$$;
create or replace function care_personnel_private.validate_command(p_tenant uuid,p_employee uuid,p_actor uuid,p_command jsonb)returns void language plpgsql security definer set search_path='' as $$
declare command jsonb:=p_command;spec jsonb;name text;typ text;v jsonb;keys text[];expected text[];begin
 if jsonb_typeof(command)is distinct from'object'or command->>'version'is distinct from'2026-10-16.1' then raise exception using errcode='22023',message='Invalid command/version';end if;
 select array_agg(k order by k)into keys from jsonb_object_keys(command)k;
 if keys is distinct from array['actorId','eventId','expectedHeadId','kind','note','occurredAt','payload','requestId','tenantId','version','employeeId']::text[] then
  select array_agg(k order by k)into expected from unnest(array['actorId','eventId','expectedHeadId','kind','note','occurredAt','payload','requestId','tenantId','version','employeeId'])k;
  if keys is distinct from expected then raise exception using errcode='22023',message='Invalid command keys';end if;
 end if;
 foreach name in array array['actorId','eventId','requestId','tenantId','employeeId']loop if not care_personnel_private.valid_id(command->name)then raise exception using errcode='22023',message='Invalid command UUID';end if;end loop;
 if not(command->'expectedHeadId'='null'::jsonb or care_personnel_private.valid_id(command->'expectedHeadId'))or not care_personnel_private.valid_text(command->'note',4000)or not care_personnel_private.valid_instant(command->'occurredAt')or jsonb_typeof(command->'payload')is distinct from'object' then raise exception using errcode='22023',message='Invalid command scope/time/note';end if;
 if(command->>'tenantId')::uuid is distinct from p_tenant or(command->>'employeeId')::uuid is distinct from p_employee or(command->>'actorId')::uuid is distinct from p_actor or command->>'requestId'=command->>'eventId' or(command->>'occurredAt')::timestamptz>clock_timestamp()then raise exception using errcode='22023',message='Invalid command scope/time';end if;
 spec:=care_personnel_private.payload_contract(command->>'kind');if spec is null then raise exception using errcode='22023',message='Unknown command kind';end if;
 select array_agg(k order by k)into expected from jsonb_object_keys(spec)k;select array_agg(k order by k)into keys from jsonb_object_keys(command->'payload')k;if keys is distinct from expected then raise exception using errcode='22023',message='Invalid payload keys';end if;
 for name,typ in select key,value#>>'{}'from jsonb_each(spec)loop
  v:=command->'payload'->name;
  if typ='text'and not care_personnel_private.valid_text(v,4000) or typ='id'and not care_personnel_private.valid_id(v)or typ='date'and not care_personnel_private.valid_date(v)or typ='date?'and not(v='null'::jsonb or care_personnel_private.valid_date(v))or typ='instant'and not care_personnel_private.valid_instant(v)then raise exception using errcode='22023',message='Invalid payload value: '||name;end if;
  if typ like'enum:%'and(jsonb_typeof(v)is distinct from'string'or not(v#>>'{}'=any(string_to_array(substr(typ,6),','))))then raise exception using errcode='22023',message='Invalid payload enum';end if;
  if typ in('money','quantity')and(jsonb_typeof(v)is distinct from'string'or(v#>>'{}')!~case when typ='money'then'^(0|[1-9][0-9]*)(\.[0-9]{1,2})?$'else'^(0|[1-9][0-9]*)(\.[0-9]{1,4})?$'end)then raise exception using errcode='22023',message='Invalid amount/quantity';end if;
  if typ like'source:%'then
   if jsonb_typeof(v)is distinct from'object'or(select count(*)from jsonb_object_keys(v))<>3 or not(v?'kind'and v?'id'and v?'snapshot')or not care_personnel_private.valid_id(v->'id')or jsonb_typeof(v->'snapshot')is distinct from'object'or not(v->>'kind'=any(string_to_array(substr(typ,8),',')))or v#>>'{snapshot,id}'is distinct from v->>'id'then raise exception using errcode='22023',message='Invalid source shape/kind';end if;
   if not exists(select 1 from jsonb_array_elements(care_personnel_private.sources(p_tenant,p_employee))x where x=v)then raise exception using errcode='40001',message='Original source changed';end if;
  end if;
  if typ='person'and(jsonb_typeof(v)is distinct from'object'or not exists(select 1 from jsonb_array_elements(care_personnel_private.people(p_tenant))x where x=v))then raise exception using errcode='40001',message='Active person changed';end if;
  if typ='accesses'then if jsonb_typeof(v)is distinct from'array'or jsonb_array_length(v)<1 then raise exception using errcode='22023',message='Access originals missing';end if;perform care_personnel_private.assert_source(p_tenant,p_employee,x)from jsonb_array_elements(v)x;if exists(select 1 from jsonb_array_elements(v)x where x->>'kind'is distinct from'access')then raise exception using errcode='22023',message='Wrong access source kind';end if;end if;
 end loop;
 if(command->>'kind')in('employment','qualification')and(command#>>'{payload,validUntil}')is not null and(command#>>'{payload,validFrom}')>(command#>>'{payload,validUntil}')then raise exception using errcode='22023',message='Invalid date order';end if;
 if(command->>'kind')in('delegation','double_staffing','coverage','absence','return_decision')and(command#>>'{payload,validFrom}')::timestamptz>(command#>>'{payload,validUntil}')::timestamptz then raise exception using errcode='22023',message='Invalid instant order';end if;
 if(command->>'kind')='payroll_time'and(command#>>'{payload,startedAt}')::timestamptz>(command#>>'{payload,endedAt}')::timestamptz then raise exception using errcode='22023',message='Invalid time order';end if;
 if(command->>'kind')='coverage'and(command#>>'{payload,accessUntil}')::timestamptz>(command#>>'{payload,validUntil}')::timestamptz then raise exception using errcode='22023',message='Coverage access outlives coverage';end if;
 if(command->>'kind')='double_staffing'and command#>>'{payload,primary,id}'=command#>>'{payload,secondary,id}'then raise exception using errcode='22023',message='Different people required';end if;
end$$;

create or replace function care_personnel_private.read_context(p_tenant uuid,p_actor uuid,p_employee uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare src jsonb;persons jsonb;h jsonb;e jsonb;begin perform care_personnel_private.actor(p_tenant,p_actor,false);e:=care_personnel_private.employee_original(p_tenant,p_employee);if e is null then raise exception using errcode='42501',message='employee unavailable';end if;insert into care_personnel_private.roots(tenant_id,employee_id)values(p_tenant,p_employee)on conflict do nothing;src:=care_personnel_private.sources(p_tenant,p_employee);persons:=care_personnel_private.people(p_tenant);h:=care_personnel_private.history(p_tenant,p_employee);return jsonb_build_object('version','2026-10-16.1','tenantId',p_tenant,'employeeId',p_employee,'actorId',p_actor,'loadedAt',to_char(clock_timestamp()at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'employee',e,'sources',jsonb_build_object('count',jsonb_array_length(src),'rows',src),'people',jsonb_build_object('count',jsonb_array_length(persons),'rows',persons),'history',h);end$$;
-- Match the receiver's existing transition contract; no original HR/payroll/access writer is called.
create or replace function care_personnel_private.validate_transition(t uuid,e uuid,a uuid,cmd jsonb)returns void language plpgsql security definer set search_path='' as $$
declare p jsonb:=cmd->'payload';prior jsonb;expected uuid;begin
 if cmd->>'kind'='delegation'then
  select x.command into prior from care_personnel_private.events x where x.tenant_id=t and x.employee_id=e and x.id=(p->>'qualificationEventId')::uuid and x.kind='qualification';
  if prior is null or prior#>>'{payload,result}'is distinct from'verified'or prior#>>'{payload,activity}'is distinct from p->>'activity'or(prior#>>'{payload,validUntil}')::date<((p->>'validUntil')::timestamptz at time zone'UTC')::date then raise exception using errcode='23514',message='Task lacks matching verified qualification';end if;
 elsif cmd->>'kind'='double_staffing'and p->>'phase'<>'planned'then
  select x.command into prior from care_personnel_private.events x where x.tenant_id=t and x.employee_id=e and x.kind='double_staffing'and x.command#>>'{payload,assignment,id}'=p#>>'{assignment,id}'and x.command#>>'{payload,phase}'='planned'order by x.sequence desc limit 1;
  if prior is null or prior#>'{payload,assignment}'is distinct from p->'assignment'or prior#>'{payload,primary}'is distinct from p->'primary'or prior#>'{payload,secondary}'is distinct from p->'secondary'then raise exception using errcode='23514',message='Acknowledgement lacks matching double staffing plan';end if;
  expected:=case p->>'phase'when'primary_ack'then(p#>>'{primary,profileId}')::uuid when'secondary_ack'then(p#>>'{secondary,profileId}')::uuid else null end;
  if expected is null or expected is distinct from a then raise exception using errcode='42501',message='Only the assigned person can acknowledge participation';end if;
 elsif cmd->>'kind'='return_decision'then
  select x.command into prior from care_personnel_private.events x where x.tenant_id=t and x.employee_id=e and x.kind='absence'and x.command#>>'{payload,absence,id}'=p#>>'{absence,id}'order by x.sequence desc limit 1;
  if prior is null or(prior#>>'{payload,validUntil}')::timestamptz>(p->>'validFrom')::timestamptz then raise exception using errcode='23514',message='Return requires a completed prior absence';end if;
 elsif cmd->>'kind'='correct'then
  if not exists(select 1 from care_personnel_private.events x where x.tenant_id=t and x.employee_id=e and x.id=(p->>'targetId')::uuid and x.kind<>'correct'and not exists(select 1 from care_personnel_private.events y where y.tenant_id=t and y.employee_id=e and y.kind='correct'and y.command#>>'{payload,targetId}'=x.id::text))then raise exception using errcode='23514',message='Only a present uncorrected original can be corrected';end if;
 end if;
end$$;
create or replace function care_personnel_private.commit_event(p_command jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare t uuid:=(p_command->>'tenantId')::uuid;e uuid:=(p_command->>'employeeId')::uuid;a uuid:=(p_command->>'actorId')::uuid;rid uuid:=(p_command->>'requestId')::uuid;eid uuid:=(p_command->>'eventId')::uuid;expected uuid:=nullif(p_command->>'expectedHeadId','')::uuid;root care_personnel_private.roots%rowtype;prior care_personnel_private.events%rowtype;actor_name text;seq bigint;receipt jsonb;begin
 actor_name:=care_personnel_private.actor(t,a,true);perform pg_advisory_xact_lock(hashtextextended(t::text||':'||e::text,0));if care_personnel_private.employee_original(t,e)is null then raise exception using errcode='42501',message='employee unavailable';end if;insert into care_personnel_private.roots(tenant_id,employee_id)values(t,e)on conflict do nothing;select*into root from care_personnel_private.roots where tenant_id=t and employee_id=e for update;select*into prior from care_personnel_private.events where tenant_id=t and request_id=rid;if found then if prior.command is distinct from p_command or prior.actor_id is distinct from a or prior.employee_id is distinct from e then raise exception using errcode='23505',message='request collision';end if;else perform care_personnel_private.validate_command(t,e,a,p_command);if root.head_id is distinct from expected then raise exception using errcode='40001',message='head changed';end if;perform care_personnel_private.validate_transition(t,e,a,p_command);seq:=coalesce((select max(sequence)+1 from care_personnel_private.events where tenant_id=t and employee_id=e),1);insert into care_personnel_private.events(id,tenant_id,employee_id,sequence,previous_id,request_id,actor_id,actor_name,occurred_at,kind,command)values(eid,t,e,seq,expected,rid,a,actor_name,(p_command->>'occurredAt')::timestamptz,p_command->>'kind',p_command)returning*into prior;update care_personnel_private.roots set head_id=eid,updated_at=clock_timestamp()where tenant_id=t and employee_id=e;end if;receipt:=jsonb_build_object('version','2026-10-16.1','requestId',rid,'command',prior.command,'event',jsonb_build_object('id',prior.id,'sequence',prior.sequence,'previousId',prior.previous_id,'tenantId',prior.tenant_id,'employeeId',prior.employee_id,'actorId',prior.actor_id,'actorName',prior.actor_name,'recordedAt',to_char(prior.recorded_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'command',prior.command));return receipt;end$$;
create or replace function care_personnel_private.confirm_event(p_tenant uuid,p_actor uuid,p_employee uuid,p_request uuid,p_command jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare e care_personnel_private.events%rowtype;begin perform care_personnel_private.actor(p_tenant,p_actor,false);select*into e from care_personnel_private.events where tenant_id=p_tenant and employee_id=p_employee and request_id=p_request;if not found or e.command is distinct from p_command then raise exception using errcode='P0P01',message='receipt unavailable';end if;return jsonb_build_object('version','2026-10-16.1','requestId',p_request,'command',e.command,'event',jsonb_build_object('id',e.id,'sequence',e.sequence,'previousId',e.previous_id,'tenantId',e.tenant_id,'employeeId',e.employee_id,'actorId',e.actor_id,'actorName',e.actor_name,'recordedAt',to_char(e.recorded_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'command',e.command));end$$;
create or replace function public.web_personnel_employees(p_tenant_id uuid,p_actor_id uuid)returns jsonb language plpgsql security invoker set search_path='' as $$declare rows jsonb;begin perform care_personnel_private.actor(p_tenant_id,p_actor_id,false);select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'tenant_id',e.tenant_id,'first_name',e.first_name,'last_name',e.last_name,'status',e.status)order by e.last_name,e.first_name,e.id),'[]'::jsonb)into rows from public.employees e where e.tenant_id=p_tenant_id;return jsonb_build_object('version','2026-10-16.1','tenantId',p_tenant_id,'actorId',p_actor_id,'count',jsonb_array_length(rows),'employees',rows);end$$;
create or replace function public.web_personnel_context(p_tenant_id uuid,p_actor_id uuid,p_employee_id uuid)returns jsonb language sql security invoker set search_path='' as $$select care_personnel_private.read_context(p_tenant_id,p_actor_id,p_employee_id)$$;
create or replace function public.web_commit_personnel_event(p_command jsonb)returns jsonb language sql security invoker set search_path='' as $$select care_personnel_private.commit_event(p_command)$$;
create or replace function public.web_confirm_personnel_event(p_tenant_id uuid,p_actor_id uuid,p_employee_id uuid,p_request_id uuid,p_command jsonb)returns jsonb language sql security invoker set search_path='' as $$select care_personnel_private.confirm_event(p_tenant_id,p_actor_id,p_employee_id,p_request_id,p_command)$$;
